(7730325, 1273333, 66597, '<td valign="top">Beautiful light and curving lines.</td>', 'Beautiful light and curving lines.', '2022-09-26 23:10:11.000000', NULL, 1),
(7730326, 1273255, 66597, '<td valign="top">I really like this, but one nitpick is your horizon seems askew. Otherwise lovely light and little story here.</td>', 'I really like this, but one nitpick is your horizon seems askew. Otherwise lovely light and little story here.', '2022-09-26 23:12:18.000000', NULL, 1),
(7730327, 1273340, 66597, '<td valign="top">A rare midday photo in color that works. Well done</td>', 'A rare midday photo in color that works. Well done', '2022-09-26 23:12:47.000000', NULL, 1),
(7730328, 1273180, 66597, '<td valign="top">An interesting and provocative take.</td>', 'An interesting and provocative take.', '2022-09-26 23:13:27.000000', NULL, 1),
(7730376, 1273333, 114285, '<td valign="top">Dont you wish you kept this for the pathway challenge, albeit I think this will still do pretty well. One of my top picks.<br/> <br/>Beautiful scenery and excellent processing. Hope you had a great day.</td>', 'Dont you wish you kept this for the pathway challenge, albeit I think this will still do pretty well. One of my top picks. Beautiful scenery and excellent processing. Hope you had a great day.', '2022-09-28 02:07:13.000000', NULL, 1),
(7730387, 1273129, 114285, '<td valign="top">Amazing shot, the clouds are dynamite! Ribbon.</td>', 'Amazing shot, the clouds are dynamite! Ribbon.', '2022-09-28 08:13:53.000000', NULL, 1),
(7730388, 1273255, 114285, '<td valign="top">Adore this shot, so sweet. Ribbon for sure.<br/> <br/>Lev? Looks like Israel again :)</td>', 'Adore this shot, so sweet. Ribbon for sure. Lev? Looks like Israel again :)', '2022-09-28 08:14:41.000000', NULL, 1),
