(7730507, 1273333, 15163, '<td valign="top">Great photo my #1 vote</td>', 'Great photo my #1 vote', '2022-09-30 09:39:48.000000', NULL, 1),
(7730510, 1273333, 65234, '<td valign="top">I do love a curvy leading line. Beautiful scene with the colorful foliage.</td>', 'I do love a curvy leading line. Beautiful scene with the colorful foliage.', '2022-09-30 12:03:20.000000', NULL, 1),
(7730511, 1272995, 65234, '<td valign="top">Just love the light here. Really interesting branch he''s perched on, too.</td>', 'Just love the light here. Really interesting branch he''s perched on, too.', '2022-09-30 12:04:30.000000', NULL, 1),
(7730512, 1273339, 65234, '<td valign="top">I like your composition, and the sky and reflections are lovely.</td>', 'I like your composition, and the sky and reflections are lovely.', '2022-09-30 12:05:33.000000', NULL, 1),
(7730513, 1273329, 65234, '<td valign="top">Puts me in mind of a lazy, hazy late summer day.</td>', 'Puts me in mind of a lazy, hazy late summer day.', '2022-09-30 12:06:22.000000', NULL, 1),
(7730514, 1273169, 65234, '<td valign="top">I hope you weren''t an unauthorized person =:O He looks like he means business.</td>', 'I hope you weren''t an unauthorized person =:O He looks like he means business.', '2022-09-30 12:07:35.000000', NULL, 1),
(7730515, 1273337, 65234, '<td valign="top">I like the idea of the light rays being leading lines. Sort of wish the whole flower was in focus, or that focus was on the nearer flower stalk.</td>', 'I like the idea of the light rays being leading lines. Sort of wish the whole flower was in focus, or that focus was on the nearer flower stalk.', '2022-09-30 12:09:09.000000', NULL, 1),
(7730516, 1273338, 65234, '<td valign="top">Dizzying.</td>', 'Dizzying.', '2022-09-30 12:09:21.000000', NULL, 1),
(7730517, 1273323, 65234, '<td valign="top">Ghosts of the building to the left and top, which I''m assuming are intentional and are therefore interesting. They go with the infinity theme. But also lots of sharpening artifacts, like the haloes around the birds and the jagged edges to most of the straight vertical lines of the building. Not so fond of those.</td>', 'Ghosts of the building to the left and top, which I''m assuming are intentional and are therefore interesting. They go with the infinity theme. But also lots of sharpening artifacts, like the haloes around the birds and the jagged edges to most of the straight vertical lines of the building. Not so fond of those.', '2022-09-30 12:13:46.000000', NULL, 1),
(7730584, 1273255, 30049, '<td valign="top">Lovely image and composition.  I like that there''s a subject for the lines to lead to.   Slight ding for not taking a moment to straighten the image (it leans to the right).</td>', 'Lovely image and composition.  I like that there''s a subject for the lines to lead to.   Slight ding for not taking a moment to straighten the image (it leans to the right).', '2022-10-02 10:16:39.000000', NULL, 1),
